export const survivorRecordDefinitions={survivorRecords:{title:'Keep a complete invented cohort beside a filtered end-of-year directory',fields:[
 ['recordOpening','Equal opening amount in each of eight invented funds (CAD)',10000,1000,100000,1000],
 ['recordOmitted','Records missing from the end-year directory: H, then G, then F',3,0,3,1],
 ['recordShift','Return adjustment applied only to omitted records (percentage points)',0,-30,60,5]
]}};
export function survivorRecordPlan(d){
 const rows=[20,12,8,4,0,-5,-15,-40].map((base,i)=>{const omitted=i>=8-d.recordOmitted,rate=(base+(omitted?d.recordShift:0))/100;return {name:'Fund '+String.fromCharCode(65+i),omitted,rate,opening:d.recordOpening,ending:d.recordOpening*(1+rate)};});
 const listed=rows.filter(r=>!r.omitted),omitted=rows.filter(r=>r.omitted),fullMean=rows.reduce((s,r)=>s+r.rate,0)/8,listedMean=listed.reduce((s,r)=>s+r.rate,0)/listed.length,omittedMean=omitted.length?omitted.reduce((s,r)=>s+r.rate,0)/omitted.length:null;
 return {rows,listed,omitted,fullMean,listedMean,omittedMean,gap:listedMean-fullMean,listedContribution:listed.reduce((s,r)=>s+r.rate,0)/8,omittedContribution:omitted.reduce((s,r)=>s+r.rate,0)/8,opening:8*d.recordOpening,ending:rows.reduce((s,r)=>s+r.ending,0)};
}
export function survivorRecordResult(kind,d){
 if(kind!=='survivorRecords')throw Error('Unknown record-selection topic.');
 const p=survivorRecordPlan(d);
 return {metrics:[['Mean return across all eight original records',p.fullMean,'percent'],['Mean return among records still listed',p.listedMean,'percent'],['Listed mean minus complete-cohort mean',p.gap,'pp'],['Ending value across all eight original positions',p.ending,'money']],note:'Original, fully observed, invented one-year cohort of eight funds A–H, each with the same opening amount. Base simple total returns, with all income retained and before fees and taxes, are +20%, +12%, +8%, +4%, 0%, −5%, −15% and −40%. All eight complete-period returns and ending values remain known, including for omitted directory records. Omission is an assumed end-of-period listing status, not an estimated closure probability, an actual liquidation or a rule that causes performance. The control omits H first, then G, then F; its return adjustment changes only the currently omitted records. No real funds, market observations, causal estimates, confidence intervals, p-values or simulated samples are used. Group means are equal-weight arithmetic means across funds over one common year. Equal opening positions with no cash flows make the full-cohort mean equal to that original buy-and-hold basket’s simple return; the filtered mean uses a smaller denominator and is not the return earned by the original whole basket. Returns are assumed complete total-return inputs; no additional fee, tax, currency change, sales charge, new entry, merger, reinvestment after liquidation or missing-period return is modeled. An omitted record is never treated as a zero ending value. The directory is seen after the return period and does not supply an investable selection rule or a future return assumption.',charts:[
  {id:'survivor-records-complete-cohort',type:'signedbar',title:'Retain every original outcome even when the end-year directory omits its record',unit:'percent',unitLabel:'One-year simple total return · eight invented funds · status assigned at period end',rows:p.rows.map(r=>({label:r.name+' · '+(r.omitted?'omitted':'still listed'),value:r.rate})),note:'All eight records are visible here so the full cohort remains auditable. A missing directory record is not a zero return or a complete loss. Each invented return covers the same full year. The adjustment changes only the omitted records and is a sensitivity assumption, not a correction estimated from real fund data.'},
  {id:'survivor-records-count-denominator',type:'stackbar',title:'Show how many original records remain in the reported denominator',unit:'count',unitLabel:'Number of invented fund records · not a survival probability',tableUnit:'Fund records',seriesNames:['Still listed','Omitted from directory'],rows:[{label:'Original cohort: eight records',values:[p.listed.length,p.omitted.length]}],note:'The segments are disjoint and add to eight. Counts describe this complete toy cohort rather than a random market sample. The listed mean divides by the first segment’s count. The complete-cohort mean divides by eight. A count does not replace the returns needed to calculate either mean.'},
  {id:'survivor-records-mean-bridge',type:'waterfall',title:'Rebuild the full-cohort mean with original-cohort weights',unit:'percent',unitLabel:'Contributions to the original cohort’s one-year mean return',rows:[{label:'Listed group: weighted share',value:p.listedContribution},{label:'Omitted group: weighted share',value:p.omittedContribution}],totalLabel:'Complete-cohort mean return',note:'Each step is the sum of that group’s individual returns divided by eight. Equivalently, it is the group mean multiplied by the group’s share of the original eight records. The steps add to the complete-cohort mean, not the unweighted sum of the two group means. With no omissions, the second contribution is zero and no omitted-group mean is defined.'},
  {id:'survivor-records-gap-sensitivity',type:'line',title:'The direction of the reporting gap depends on the omitted outcomes',unit:'percent',unitLabel:'Equal-weight one-year mean return · reporting status held fixed',xMin:-30,xLabel:'Omitted-group shift (pp)',xTicks:[{value:-30,label:'−30'},{value:0,label:'0'},{value:30,label:'+30'},{value:60,label:'+60'}],series:[{name:'Complete original cohort',rows:Array.from({length:19},(_,i)=>{const x=-30+5*i;return {x,value:survivorRecordPlan({...d,recordShift:x}).fullMean};})},{name:'Records still listed',dash:true,rows:Array.from({length:19},(_,i)=>{const x=-30+5*i;return {x,value:survivorRecordPlan({...d,recordShift:x}).listedMean};})}],note:'The horizontal adjustment is added in percentage points to the currently omitted records only. The listed group’s returns remain unchanged. Omitting sufficiently strong performers can make the listed mean lower than the complete-cohort mean. If no records are omitted, neither group calculation responds to this adjustment and the two curves coincide. This illustration cannot measure the size or sign of bias in an actual database.'}
 ]};
}
